window.renderPincabSertifikasi = function() {
    const agents = window.getPincabBranchAgents();

    // Hitung Ringkasan Sertifikasi
    const totalAgents = agents.length;
    const l3Pass = agents.filter(a => a.certifications && a.certifications.level3 && a.certifications.level3.status === 'Lulus').length;
